 {page==='Knowledge Graph'&&<section className="panel graph-workspace"><div className="graph-toolbar">{kgView==='table'&&<label className="input-search"><Search size={15}/><input placeholder="Find an entity or source file…" aria-label="Filter graph entities" value={query} onChange={e=>{setQuery(e.target.value);setOffset(0)}}/></label>}{kgView==='table'&&<select aria-label="Entity type" value={filter} onChange={e=>{setFilter(e.target.value);localStorage.setItem('onto.filter',e.target.value);setOffset(0)}}><option value="">All entity types</option>{state?.entity_types.map((t:Obj)=><option key={t.type} value={t.type}>{t.type} ({t.count})</option>)}</select>}<div className="segmented kg-layers" role="group" aria-label="Graph layer">{([['code',Code2,'Code graph'],['domain',Shapes,'Domain ontology'],['split',Columns2,'Side by side']] as ['code'|'domain'|'split',LucideIcon,string][]).map(([l,Icon,label])=><button key={l} aria-pressed={layer===l} onClick={()=>setLayer(l)}><Icon size={15}/>{label}</button>)}</div>{kgView!=='table'&&layer!=='split'&&sid&&<span className="kg-summary">{layer==='code'?<><strong>{(state?.entity_count||0).toLocaleString()}</strong> entities · <strong>{(state?.edge_count||0).toLocaleString()}</strong> connections · commit {short(state?.snapshot?.commit)}</>:<><strong>{(state?.ontology?.concepts||[]).filter((c:Obj)=>c.layer==='domain').length}</strong> domain concepts · ontology {state?.ontology?.status||'not created'}</>}</span>}{layer!=='split'&&<div className="segmented kg-views">{([['map',Network,'Map'],['structure',FolderTree,'Structure'],['focus',Crosshair,'Focus'],['diagram',LayoutDashboard,'Diagram'],['coverage',Gauge,'Coverage'],['query',Braces,'SPARQL'],['table',Table2,'Table']] as [string,LucideIcon,string][]).filter(([v])=>layer==='code'?!['diagram','coverage','query'].includes(v):v!=='table').map(([v,Icon,label])=><button key={v} aria-pressed={kgView===v} onClick={()=>setKgView(v)}><Icon size={15}/>{label}</button>)}</div>}{source&&sid&&<ExternalTools sourceId={source}/>}<Button variant="secondary" icon={kgFull?Minimize2:Maximize2} onClick={()=>setKgFull(!kgFull)} title={kgFull?'Exit full screen':'Use the whole window for the graph'}>{kgFull?'Exit full screen':'Full screen'}</Button></div>{kgView==='table'&&neighbor&&<div className="filter-note">Showing a one-hop neighbourhood<Button icon={X} variant="text" onClick={()=>setNeighbor('')}>Clear</Button></div>}{layer==='code'&&kgView==='table'?(graphError?<div className="alert error">{graphError}<Button onClick={()=>load()}>Retry</Button></div>:graphLoading?<div className="loading"><Loader2 className="spin"/>Loading graph slice…</div>:!graph.nodes.length?<Empty title={sid?'No matching entities':'Your graph starts with a source'} description={sid?'Change the search or type filter to explore more entities.':'Analyse a repository to build an evidence-backed technical graph.'} action={<Button onClick={()=>sid?(setQuery(''),setFilter(''),setNeighbor('')):setAdd(true)}>{sid?'Clear filters':'Connect source'}</Button>}/>:<div className="table-scroll"><table><thead><tr><th>Entity</th><th>Type</th><th>Source location</th><th>Extraction</th><th>Status</th></tr></thead><tbody>{graph.nodes.map((n:Entity)=><tr key={n.id} onClick={()=>setEntity(n)}><td><button className="text-link">{n.name}</button></td><td><Badge>{n.type}</Badge></td><td className="mono">{n.path}:{n.line}</td><td>{n.method}</td><td><Badge tone="green">Extracted fact</Badge></td></tr>)}</tbody></table></div>):!sid?<Empty title="Your graph starts with a source" description="Analyse a repository to build an evidence-backed technical graph." action={<Button onClick={()=>setAdd(true)}>Connect source</Button>}/>:layer==='split'?<React.Suspense fallback={<div className="loading"><Loader2 className="spin"/>Loading explorer…</div>}><SplitExplorer snapshotId={sid} colors={colors} mappings={shownMappings} ontology={shownOntology} revision={revisionRef.current.value} onCrossLink={crossLink} onOpenEntity={e=>setEntity(e as Entity)}/></React.Suspense>:<React.Suspense fallback={<div className="loading"><Loader2 className="spin"/>Loading explorer…</div>}><KnowledgeExplorer key={layer} mode={layer} snapshotId={sid} view={kgView as ExplorerView} onView={setKgView} colors={colors} mappings={shownMappings} ontology={shownOntology} revision={revisionRef.current.value} live={live} unresolved={state?.snapshot?.unresolved_references||0} focusRequest={layer==='code'?focusRequest:conceptRequest} onFocusHandled={()=>layer==='code'?setFocusRequest(null):setConceptRequest(null)} onCrossLink={crossLink} onOpenEntity={e=>setEntity(e as Entity)} semantic={layer==='domain'?semantic:undefined} onGenerate={source&&!liveJob?()=>setGenerateOpen(true):undefined}/></React.Suspense>}{layer==='code'&&kgView==='table'&&<><div className="graph-footer"><div className="legend">{(state?.entity_types||[]).map((t:Obj)=><span key={t.type}><i style={{background:colors[t.type]}}/>{t.type}</span>)}</div><div className="pagination"><span>{graph.nodes.length?offset+1:0}–{Math.min(offset+graph.nodes.length,graph.total)} of {graph.total}</span><Button disabled={offset===0} onClick={()=>setOffset(Math.max(0,offset-24))}>Previous</Button><Button disabled={offset+24>=graph.total} onClick={()=>setOffset(offset+24)}>Next</Button></div></div><div className="panel-note"><Info size={14}/>Rows are paginated on the server; use Map, Structure or Focus to explore connections. Unresolved references: {state?.snapshot?.unresolved_references||0}. Static analysis does not capture every runtime dependency.</div></>}</section>}
 {page==='Outputs'&&<OutputsPage source={current} state={state} onChanged={()=>load(true)}/>}
